#!/usr/bin/env python3
"""
Simple mock deployment orchestrator for testing
Run with: python3 test_orchestrator.py
"""

from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import sys

class MockOrchestrator(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path == '/api/deploy-config':
            content_length = int(self.headers['Content-Length'])
            post_data = self.rfile.read(content_length)

            try:
                config_data = json.loads(post_data.decode('utf-8'))

                print(f"[Mock Orchestrator] Received deploy config:")
                print(f"  Path: {self.path}")
                print(f"  Headers: {dict(self.headers)}")
                print(f"  Config data keys: {list(config_data.keys())}")

                # Log first few values (masking secrets)
                for i, (key, value) in enumerate(config_data.items()):
                    if i < 3:  # Show first 3 values
                        masked_value = "[MASKED]" if any(secret_word in key.upper() for secret_word in ["SECRET", "PASSWORD", "TOKEN", "KEY", "PASS"]) else value
                        print(f"  {key}: {masked_value}")
                    else:
                        print(f"  ... and {len(config_data) - 3} more keys")
                        break

                # Return success
                self.send_response(201)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {
                    "status": "success",
                    "message": "Configuration received and stored",
                    "received_keys": len(config_data),
                    "audit_id": "AUDIT-20240609-001"
                }
                self.wfile.write(json.dumps(response).encode('utf-8'))

            except json.JSONDecodeError as e:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                error_response = {
                    "status": "error",
                    "message": f"Invalid JSON: {str(e)}"
                }
                self.wfile.write(json.dumps(error_response).encode('utf-8'))

        else:
            self.send_response(404)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            error_response = {
                "status": "error",
                "message": f"Endpoint not found: {self.path}"
            }
            self.wfile.write(json.dumps(error_response).encode('utf-8'))

    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        response = {
            "status": "running",
            "service": "Mock Deployment Orchestrator",
            "endpoints": {
                "POST /api/deploy-config": "Receive deployment configuration"
            }
        }
        self.wfile.write(json.dumps(response).encode('utf-8'))

    def log_message(self, format, *args):
        # Suppress default logging
        pass

def run_server(port=47301):
    server_address = ('', port)
    httpd = HTTPServer(server_address, MockOrchestrator)
    print(f"Starting mock deployment orchestrator on port {port}")
    print(f"Use Ctrl+C to stop")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down mock orchestrator...")
        httpd.server_close()

if __name__ == '__main__':
    run_server()

