const port = 47301;
const endpoint = '/api/deploy-config';

const server = http.createServer((req, res) => {
    if (req.method === 'POST' && req.url === endpoint) {
        let body = '';

        req.on('data', chunk => {
            body += chunk.toString();
        });

        req.on('end', () => {
            console.log('📥 Received deployment configuration:');
            console.log('📊 Headers:', req.headers);
            console.log('📦 Body:', body);

            try {
                const config = JSON.parse(body);
                console.log('✅ Parsed JSON configuration:');
                console.log(JSON.stringify(config, null, 2));

                // Log audit information
                console.log(`\n📋 Audit Log Entry:`);
                console.log(`   Timestamp: ${new Date().toISOString()}`);
                console.log(`   Variables: ${Object.keys(config).length}`);
                console.log(`   Sample variables:`);
                Object.entries(config).slice(0, 3).forEach(([key, value]) => {
                    console.log(`     - ${key}: ${value.substring(0, 20)}${value.length > 20 ? '...' : ''}`);
                });

                // Send success response
                res.writeHead(201, { 
                    'Content-Type': 'application/json',
                    'Access-Control-Allow-Origin': '*'
                });
                res.end(JSON.stringify({
                    status: 'success',
                    message: 'Configuration received and logged for audit',
                    timestamp: new Date().toISOString(),
                    config_received: true
                }));
            } catch (error) {
                console.log('❌ JSON parse error:', error.message);

                res.writeHead(400, { 
                    'Content-Type': 'application/json',
                    'Access-Control-Allow-Origin': '*'
                });
                res.end(JSON.stringify({
                    status: 'error',
                    message: 'Invalid JSON',
                    error: error.message
                }));
            }
        });
    } else {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
            status: 'error',
            message: 'Endpoint not found'
        }));
    }
});

server.listen(port, () => {
    console.log(`🚀 Mock orchestrator server running at http://localhost:${port}`);
    console.log(`📤 POST endpoint: http://localhost:${port}${endpoint}`);
    console.log('📝 Ready to receive deployment configuration...\n');
});

// Handle graceful shutdown
process.on('SIGINT', () => {
    console.log('\n👋 Shutting down mock orchestrator server');
    server.close(() => {
        process.exit(0);
    });
});

