#!/usr/bin/env python3
"""
Mock deployment orchestrator for testing deploy.sh
Run with: python3 mock_orchestrator.py
"""

from http.server import HTTPServer, BaseHTTPRequestHandler
import json
import sys
from datetime import datetime

class MockOrchestratorHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path == '/api/deploy-config':
            content_length = int(self.headers['Content-Length'])
            post_data = self.rfile.read(content_length)

            try:
                data = json.loads(post_data.decode('utf-8'))

                # Log the received data
                print(f"\n=== Received deployment config ===")
                print(f"Time: {datetime.now().isoformat()}")
                print(f"Deployment name: {data.get('deployment_name')}")
                print(f"Timestamp: {data.get('timestamp')}")
                print(f"Config variables: {len(data.get('config', {}))}")

                # Display config (masking values for security)
                config = data.get('config', {})
                for key, value in config.items():
                    masked_value = value[:5] + "..." + value[-5:] if len(value) > 15 else "***"
                    print(f"  {key}: {masked_value}")

                # Simulate validation
                if 'DATABASE_URL' not in config:
                    response = {
                        "status": "error",
                        "message": "Missing required DATABASE_URL",
                        "code": "MISSING_REQUIRED_FIELD"
                    }
                    self.send_response(400)
                else:
                    response = {
                        "status": "success",
                        "message": "Config accepted",
                        "audit_id": f"AUDIT-{datetime.now().strftime('%Y%m%d%H%M%S')}",
                        "received_at": datetime.now().isoformat()
                    }
                    self.send_response(201)

                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                self.wfile.write(json.dumps(response).encode('utf-8'))

            except json.JSONDecodeError:
                self.send_response(400)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {"status": "error", "message": "Invalid JSON"}
                self.wfile.write(json.dumps(response).encode('utf-8'))
        else:
            self.send_response(404)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            response = {"status": "error", "message": "Not found"}
            self.wfile.write(json.dumps(response).encode('utf-8'))

    def do_GET(self):
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        response = {
            "service": "Mock Deployment Orchestrator",
            "version": "1.0.0",
            "endpoints": {
                "POST /api/deploy-config": "Accept deployment configuration for audit"
            }
        }
        self.wfile.write(json.dumps(response).encode('utf-8'))

    def log_message(self, format, *args):
        # Suppress default HTTP logging
        pass

def run_server(port=47301):
    server_address = ('', port)
    httpd = HTTPServer(server_address, MockOrchestratorHandler)
    print(f"Mock orchestrator running on http://localhost:{port}")
    print("Press Ctrl+C to stop")
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down mock orchestrator...")
        httpd.server_close()

if __name__ == '__main__':
    run_server()

